// 1. Validate incoming payload
const body = $input.first().json.body || $input.first().json;
const organizationId = body.organizationId || '00000000-0000-0000-0000-000000000001';
const rawQuery = String(body.query || '').trim();
const conversationId = body.conversationId || `conv-${Date.now()}`;
const sessionId = body.sessionId || `session-${Date.now()}`;
const history = Array.isArray(body.history) ? body.history : [];

if (!rawQuery) {
  throw new Error('Query text is required.');
}

return [{
  json: {
    organizationId,
    conversationId,
    sessionId,
    rawQuery,
    history,
    timestamp: new Date().toISOString(),
    requestId: `req-${Date.now()}`
  }
}];

// Evidence Synthesizer & Reranker
const searchResults = $('node-postgres-retriever').all().map(i => i.json);
const kgResults = $('node-kg-retriever').all().map(i => i.json);
const analysis = $('node-query-refiner').first().json;

// 1. Deduplicate & filter
const seen = new Set();
const evidencePack = [];
let sourceIndex = 1;

for (const row of searchResults) {
  const key = (row.content || '').slice(0, 80).toLowerCase();
  if (!seen.has(key) && row.content) {
    seen.add(key);
    evidencePack.push({
      tag: `[S${sourceIndex}]`,
      header: `[S${sourceIndex} | ${row.entity_type || 'CHUNK'} | /services]`,
      text: row.content
    });
    sourceIndex++;
  }
}

for (const row of kgResults) {
  const key = `kg-${row.name}`.toLowerCase();
  if (!seen.has(key) && row.name) {
    seen.add(key);
    evidencePack.push({
      tag: `[S${sourceIndex}]`,
      header: `[S${sourceIndex} | ${row.entity_type} | ${row.name}]`,
      text: `${row.name} (${row.entity_type}): ${JSON.stringify(row.attributes || {})}`
    });
    sourceIndex++;
  }
}

const formattedEvidence = evidencePack.map(e => `${e.header}\n${e.text}`).join('\n\n');

return [{
  json: {
    analysis,
    evidenceText: formattedEvidence,
    evidenceCount: evidencePack.length,
    sources: evidencePack.map(e => ({ tag: e.tag, header: e.header }))
  }
}];

// Grounding Verification & Output Sanitizer
const rawAnswer = $input.first().json.text || $input.first().json.response || '';
const evidenceText = $('node-evidence-synthesizer').first().json.evidenceText || '';
const rawQuery = $('node-payload-validator').first().json.rawQuery || '';

// 1. Strip raw system tokens
let sanitized = rawAnswer
  .replace(/\[INDUSTRY\]/g, '')
  .replace(/\[COMPANY\]/g, '')
  .replace(/\[SERVICE\]/g, '')
  .replace(/\[TECHNOLOGY\]/g, '')
  .trim();

// 2. Build Suggested Actions
const actions = [
  { label: 'Schedule Architecture Consultation', href: '#contact', variant: 'primary' },
  { label: 'Explore Engineering Capabilities', href: '#services', variant: 'secondary' }
];

return [{
  json: {
    status: 'success',
    answer: sanitized,
    suggested_actions: actions,
    sources: $('node-evidence-synthesizer').first().json.sources,
    metadata: {
      refined_query: $('node-query-refiner').first().json.standalone_question,
      language: $('node-query-refiner').first().json.language,
      evidence_chunks: $('node-evidence-synthesizer').first().json.evidenceCount,
      processed_at: new Date().toISOString()
    }
  }
}];
